import resource, redis
def rss(): return resource.getrusage(resource.RUSAGE_SELF).ru_maxrss // 1024
r = redis.Redis(host='127.0.0.1', port=6379, decode_responses=False, socket_timeout=30)
keys = list(r.scan_iter(db=0, count=1000))
tp = r.pipeline(transaction=False)
for k in keys: tp.type(k)
kt = tp.execute()
print('all types ok', len(kt), 'maxrss MB:', rss())
vp = r.pipeline(transaction=False)
n=0
for k, t in zip(keys, kt):
    t2 = t if isinstance(t, bytes) else t.encode()
    if t2 == b'string': vp.execute_command('GET', k)
    elif t2 == b'list': vp.execute_command('LRANGE', k, 0, -1)
    elif t2 == b'hash': vp.execute_command('HGETALL', k)
    elif t2 == b'set': vp.execute_command('SMEMBERS', k)
    elif t2 == b'zset': vp.execute_command('ZRANGE', k, 0, -1, 'WITHSCORES')
    elif t2 == b'stream': vp.execute_command('XRANGE', k, '-', '+')
    n+=1
vals = vp.execute()
print('all values ok', n, 'maxrss MB:', rss())
import sys
sz = sum(sys.getsizeof(v) if not isinstance(v, list) else sum(sys.getsizeof(x) for x in v) for v in vals)
print('approx vals bytes:', sz)
